{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "In mice, systemic 211At-AITM produced extremely low brain radioactivity in adult and aged animals despite high brain mGluR1 expression, indicating no meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In nonhuman primates, raltitrexed CSF penetration was only 0.6–2.0% and detectable only at the 10 mg/m2 dose, indicating limited CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In humans, 68Ga-PSMA-11 showed no brain uptake on PET/CT, consistent with failure to cross the blood–brain barrier.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved direct in-vivo records across mice, nonhuman primates, and humans show negligible brain uptake or CSF penetration after systemic administration; therefore meaningful CNS access is not supported.",
  "evidence_gaps": [
    "Quantitative unbound brain concentrations and therapeutic-dose pharmacokinetics are not reported, but direct brain/CSF uptake is consistently low."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

